<?php

/* @autogenerated */
declare(strict_types=1);

namespace Civi\Lughauth\Features\Access\UserGroupMembership\Application\Service\Visibility;

use Psr\EventDispatcher\EventDispatcherInterface;
use Iterator;
use Throwable;
use Civi\Lughauth\Features\Access\User\Application\Service\Visibility\UserVisibilityService;
use Civi\Lughauth\Features\Access\RelyingParty\Application\Service\Visibility\RelyingPartyVisibilityService;
use Civi\Lughauth\Features\Access\TrustedClient\Application\Service\Visibility\TrustedClientVisibilityService;
use Civi\Lughauth\Shared\Exception\NotFoundException;
use Civi\Lughauth\Features\Access\UserGroupMembership\Domain\UserGroupMembershipRef;
use Civi\Lughauth\Features\Access\UserGroupMembership\Domain\UserGroupMembershipAttributes;
use Civi\Lughauth\Features\Access\UserGroupMembership\Domain\UserGroupMembership;
use Civi\Lughauth\Features\Access\UserGroupMembership\Domain\Gateway\UserGroupMembershipFilter;
use Civi\Lughauth\Features\Access\UserGroupMembership\Domain\Gateway\UserGroupMembershipCursor;
use Civi\Lughauth\Features\Access\UserGroupMembership\Domain\Gateway\UserGroupMembershipReadGateway;
use Civi\Lughauth\Features\Access\UserGroupMembership\Domain\Gateway\UserGroupMembershipSlide;
use Civi\Lughauth\Features\Access\UserGroupMembership\Domain\Gateway\UserGroupMembershipWriteGateway;
use Civi\Lughauth\Shared\Observability\LoggerAwareTrait;
use Civi\Lughauth\Shared\Observability\TracerAwareTrait;

class UserGroupMembershipVisibilityService
{
    use LoggerAwareTrait;
    use TracerAwareTrait;

    public function __construct(
        private readonly EventDispatcherInterface $dispatcher,
        private readonly UserGroupMembershipReadGateway $readGateway,
        private readonly UserGroupMembershipWriteGateway $writeGateway,
        private readonly UserVisibilityService $userVisibilityService,
        private readonly RelyingPartyVisibilityService $relyingPartyVisibilityService,
        private readonly TrustedClientVisibilityService $trustedClientVisibilityService
    ) {
    }

    public function prepareVisibleDataInList(UserGroupMembership $content): UserGroupMembershipAttributes
    {
        return $this->prepareVisibleDataCallback($content, true);
    }
    public function prepareVisibleData(UserGroupMembership $content): UserGroupMembershipAttributes
    {
        return $this->prepareVisibleDataCallback($content, false);
    }
    public function copyWithFixed(UserGroupMembershipAttributes $attributes, ?UserGroupMembership $original = null): UserGroupMembershipAttributes
    {
        $this->logDebug("Copy with fixed for User group membership");
        $span = $this->startSpan("Copy with fixed for  User group membership");
        try {
            $visible = $this->visiblesReferences($attributes);
            $fixed = $this->fieldsToFix($original);
            foreach ($fixed as $field) {
                $visible->unset($field);
            }
            $result = $this->dispatcher->dispatch(new UserGroupMembershipPresetValues($attributes, $original));
            return $result->attributes;
        } catch (Throwable $ex) {
            $span->recordException($ex);
            throw $ex;
        } finally {
            $span->end();
        }
    }

    public function copyWithHidden(UserGroupMembershipAttributes $attributes, ?UserGroupMembership $original = null): UserGroupMembershipAttributes
    {
        $this->logDebug("Copy with hidden for User group membership");
        $span = $this->startSpan("Copy with hidden for  User group membership");
        try {
            $hidden = $this->fieldsToHide($original);
            foreach ($hidden as $field) {
                $attributes->unset($field);
            }
            return $attributes;
        } catch (Throwable $ex) {
            $span->recordException($ex);
            throw $ex;
        } finally {
            $span->end();
        }
    }

    public function checkVisibility(Iterator|string|UserGroupMembershipRef $value): bool
    {
        $this->logDebug("Check visibility of an iterator for User group membership");
        $span = $this->startSpan("Check visibility of an iterator for  User group membership");
        try {
            if (is_string($value)) {
                return !!$this->retrieveVisibleForUpdate(new UserGroupMembershipRef($value));
            } elseif ($value instanceof UserGroupMembershipRef) {
                return !!$this->retrieveVisibleForUpdate($value);
            } elseif ($value instanceof Iterator) {
                $ids = [];
                foreach ($value as $val) {
                    $ids[] = $val->uid();
                }
                $filter = new UserGroupMembershipFilter(uids: $ids);
                return count($ids) == $this->countVisibles($filter);
            } else {
                return false;
            }
        } catch (Throwable $ex) {
            $span->recordException($ex);
            throw $ex;
        } finally {
            $span->end();
        }
    }
    public function listVisibles(UserGroupMembershipFilter $filter, ?UserGroupMembershipCursor $cursor = null): UserGroupMembershipSlide
    {
        $this->logDebug("List visibles for User group membership");
        $span = $this->startSpan("List visibles for  User group membership");
        try {
            $visibleFilter = $this->applyPreVisibilityFilter($filter);
            $result = $this->readGateway->list($visibleFilter, $cursor);
            return $result->slide(function (UserGroupMembership $item): bool {
                return $this->evaluatePostVisibility($item);
            });
        } catch (Throwable $ex) {
            $span->recordException($ex);
            throw $ex;
        } finally {
            $span->end();
        }
    }
    public function countVisibles(UserGroupMembershipFilter $filter): int
    {
        $this->logDebug("Count visibles for User group membership");
        $span = $this->startSpan("Count visibles for  User group membership");
        try {
            $visibleFilter = $this->applyPreVisibilityFilter($filter);
            return $this->readGateway->count($visibleFilter);
        } catch (Throwable $ex) {
            $span->recordException($ex);
            throw $ex;
        } finally {
            $span->end();
        }
    }
    public function listVisiblesForUpdate(UserGroupMembershipFilter $filter, ?UserGroupMembershipCursor $cursor = null): UserGroupMembershipSlide
    {
        $this->logDebug("List visibles for update for User group membership");
        $span = $this->startSpan("List visibles for update for  User group membership");
        try {
            $visibleFilter = $this->applyPreVisibilityFilter($filter);
            $result = $this->writeGateway->listForUpdate($visibleFilter, $cursor);
            return $result->slide(function (UserGroupMembership $item): bool {
                return $this->evaluatePostVisibility($item);
            });
        } catch (Throwable $ex) {
            $span->recordException($ex);
            throw $ex;
        } finally {
            $span->end();
        }
    }
    public function countVisiblesForUpdate(UserGroupMembershipFilter $filter): int
    {
        $this->logDebug("Count visibles for update for User group membership");
        $span = $this->startSpan("Count visibles for update for  User group membership");
        try {
            $visibleFilter = $this->applyPreVisibilityFilter($filter);
            return $this->writeGateway->countForUpdate($visibleFilter);
        } catch (Throwable $ex) {
            $span->recordException($ex);
            throw $ex;
        } finally {
            $span->end();
        }
    }
    public function retrieveVisible(UserGroupMembershipRef $ref): ?UserGroupMembership
    {
        $this->logDebug("Retrieve visible for User group membership");
        $span = $this->startSpan("Retrieve visible for  User group membership");
        try {
            $filter = new UserGroupMembershipFilter(uids: [$ref->uid()]);
            $visibleFilter = $this->applyPreVisibilityFilter($filter);
            if ($readed = $this->readGateway->retrieve($visibleFilter)) {
                return $this->evaluatePostVisibility($readed) ? $readed : null;
            } else {
                return null;
            }
        } catch (Throwable $ex) {
            $span->recordException($ex);
            throw $ex;
        } finally {
            $span->end();
        }
    }
    public function retrieveVisibleForUpdate(UserGroupMembershipRef $ref): ?UserGroupMembership
    {
        $this->logDebug("Retrieve visible for update for User group membership");
        $span = $this->startSpan("Retrieve visible for update for  User group membership");
        try {
            $filter = new UserGroupMembershipFilter(uids: [$ref->uid()]);
            $visibleFilter = $this->applyPreVisibilityFilter($filter);
            if ($readed = $this->writeGateway->retrieveForUpdate($visibleFilter)) {
                return $this->evaluatePostVisibility($readed) ? $readed : null;
            } else {
                return null;
            }
        } catch (Throwable $ex) {
            $span->recordException($ex);
            throw $ex;
        } finally {
            $span->end();
        }
    }
    public function fieldsToFix(?UserGroupMembershipRef $ref = null): array
    {
        $this->logDebug("Check fields to fix for User group membership");
        $span = $this->startSpan("Check fields for fix for User group membership");
        try {
            $result = $this->dispatcher->dispatch(new UserGroupMembershipCollectNonEditableFields(UserGroupMembership::calculatedFields(), $ref));
            return array_values(array_unique(array_merge($this->fieldsToHide($ref), $result->fields)));
        } catch (Throwable $ex) {
            $span->recordException($ex);
            throw $ex;
        } finally {
            $span->end();
        }
    }

    public function fieldsToHide(?UserGroupMembershipRef $ref = null): array
    {
        $this->logDebug("Check fields to hide for User group membership");
        $span = $this->startSpan("Check fields to hide for  User group membership");
        try {
            $result = $this->dispatcher->dispatch(new UserGroupMembershipCollectNonVisibleFields([], $ref));
            return array_values(array_unique($result->fields));
        } catch (Throwable $ex) {
            $span->recordException($ex);
            throw $ex;
        } finally {
            $span->end();
        }
    }

    private function visiblesReferences(UserGroupMembershipAttributes $attributes): UserGroupMembershipAttributes
    {
        $this->logDebug("Check visibility of parent references for User group membership");
        $span = $this->startSpan("Check visibility of parent references for  User group membership");
        try {
            $user = $attributes->getUser();
            if (null !== $user && !$this->userVisibilityService->checkVisibility($user)) {
                throw new NotFoundException("Unknown User " . ($user->uid() ?? 'no-id'));
            }
            $relyingParty = $attributes->getRelyingParty();
            if (null !== $relyingParty && !$this->relyingPartyVisibilityService->checkVisibility($relyingParty)) {
                throw new NotFoundException("Unknown RelyingParty " . ($relyingParty->uid() ?? 'no-id'));
            }
            $trustedClient = $attributes->getTrustedClient();
            if (null !== $trustedClient && !$this->trustedClientVisibilityService->checkVisibility($trustedClient)) {
                throw new NotFoundException("Unknown TrustedClient " . ($trustedClient->uid() ?? 'no-id'));
            }
            return $attributes;
        } catch (Throwable $ex) {
            $span->recordException($ex);
            throw $ex;
        } finally {
            $span->end();
        }
    }
    private function applyPreVisibilityFilter(UserGroupMembershipFilter $filter): UserGroupMembershipFilter
    {
        $this->logDebug("Compose visibility filter for User group membership");
        $span = $this->startSpan("Compose visibility filter for  User group membership");
        try {
            $result = $this->dispatcher->dispatch(new UserGroupMembershipRestrictFilterToVisibility($filter));
            return $result->userGroupMembershipFilter;
        } catch (Throwable $ex) {
            $span->recordException($ex);
            throw $ex;
        } finally {
            $span->end();
        }
    }
    private function evaluatePostVisibility(UserGroupMembership $value): bool
    {
        $this->logDebug("Check if item is visible for User group membership");
        $span = $this->startSpan("Check if item is visible for  User group membership");
        try {
            $result = $this->dispatcher->dispatch(new UserGroupMembershipVisibilityCheck(true, $value));
            return $result->visible;
        } catch (Throwable $ex) {
            $span->recordException($ex);
            throw $ex;
        } finally {
            $span->end();
        }
    }
    private function prepareVisibleDataCallback(UserGroupMembership $content, bool $inlist): UserGroupMembershipAttributes
    {
        $this->logDebug("Prepare hydration to visible data for User group membership");
        $span = $this->startSpan("Prepare hydration to visible data for User group membership");
        try {
            $attributes = $content->toAttributes();
            $result = $this->dispatcher->dispatch(new UserGroupMembershipEnrichForView($content, $inlist, $attributes));
            return $result->getAttributes();
        } catch (Throwable $ex) {
            $span->recordException($ex);
            throw $ex;
        } finally {
            $span->end();
        }
    }
}
